package org.bukkit; public class Location implements Cloneable { World world; double x,y,z;float yaw,pitch; public Location(World w,double x,double y,double z){this(w,x,y,z,0,0);}public Location(World w,double x,double y,double z,float yaw,float pitch){world=w;this.x=x;this.y=y;this.z=z;this.yaw=yaw;this.pitch=pitch;} public World getWorld(){return world;}public void setWorld(World w){world=w;} public double getX(){return x;}public double getY(){return y;}public double getZ(){return z;} public float getYaw(){return yaw;}public float getPitch(){return pitch;} public void setX(double x){this.x=x;} public void setY(double y){this.y=y;}public void setZ(double z){this.z=z;} public Location clone(){return new Location(world,x,y,z,yaw,pitch);} }
